namespace ghidra.feature.vt.gui.util;






using docking.widgets.table;
using generic.theme.GThemeDefaults;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.symbol;
using ghidra.util.table;

public class VTSymbolRenderer : GhidraTableCellRenderer {

	private SymbolInspector inspector;

	public VTSymbolRenderer(ServiceProvider serviceProvider, JComponent repaintComponent) {
		inspector = new SymbolInspector(serviceProvider, repaintComponent);
	}

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		base.getTableCellRendererComponent(data);

		object value = data.getValue();
		bool isSelected = data.isSelected();

		handleSymbol(value, isSelected);
		return this;
	}

	private void handleSymbol(object value, bool isSelected) {
		setBold();
		if (!isSelected) {
			Color color = Colors.FOREGROUND;
			if (value is Symbol) {
				Symbol s = (Symbol) value;
				color = inspector.getColor(s);
			}
			setForeground(color);
		}
	}
}
